/**
 * Batch 4 — ~110 verified India Quiz questions.
 * 10 per category × 11 categories = 110.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string;
  categoryId: string;
  text: string;
  options: [string, string, string, string];
  correctIndex: number;
  explanation: string;
  source: string;
  difficulty: 'easy' | 'medium' | 'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk: General Knowledge (10) ═══
  { slug: 'gk-indian-postal-system-1854', categoryId: 'cat-gk', text: 'India\'s first postage stamp was issued in which year?', options: ['1837', '1852', '1854', '1873'], correctIndex: 2, explanation: 'India\'s first postage stamp was issued on 1 October 1854. It featured a half-anna stamp with the profile of Queen Victoria. The Indian postal system is the most widely distributed in the world.', source: 'India Post / Department of Posts, Ministry of Communications', difficulty: 'medium' },
  { slug: 'gk-longest-tunnel-rail-india', categoryId: 'cat-gk', text: 'Which is the longest railway tunnel in India?', options: ['Pir Panjal Tunnel (Banihal)', 'Karbude Tunnel (Konkan Railway)', 'Tike Tunnel (Konkan Railway)', 'Sangaldan Tunnel'], correctIndex: 0, explanation: 'The Pir Panjal Railway Tunnel (also called Banihal-Qazigund tunnel) is the longest railway tunnel in India at 11.2 km, on the Udhampur-Srinagar-Baramulla rail link. It passes through the Pir Panjal mountain range.', source: 'Indian Railways / Ministry of Railways', difficulty: 'hard' },
  { slug: 'gk-national-police-commemoration-day', categoryId: 'cat-gk', text: 'Police Commemoration Day in India is observed on which date to honour police personnel who died in the line of duty?', options: ['26 November', '21 October', '15 August', '10 September'], correctIndex: 1, explanation: 'Police Commemoration Day is observed on 21 October each year. It commemorates the 10 CRPF personnel who died in a Chinese ambush at Hot Springs, Ladakh on 21 October 1959.', source: 'Ministry of Home Affairs / Bureau of Police Research and Development', difficulty: 'medium' },
  { slug: 'gk-mpi-blpi-index-india', categoryId: 'cat-gk', text: 'India launched the Multidimensional Poverty Index (MPI) report in collaboration with which organisation?', options: ['World Bank', 'United Nations Development Programme (UNDP)', 'International Monetary Fund (IMF)', 'Asian Development Bank (ADB)'], correctIndex: 1, explanation: 'India\'s MPI report was launched in collaboration with UNDP and the Oxford Poverty and Human Development Initiative (OPHI). According to the 2023 MPI report, 415 million people exited multidimensional poverty in India between 2005-06 and 2019-21.', source: 'NITI Aayog / UNDP India', difficulty: 'hard' },
  { slug: 'gk-isro-100-mission', categoryId: 'cat-gk', text: 'ISRO launched its 100th mission from Sriharikota in October 2024. What was the payload?', options: ['Chandrayaan-3', 'Aditya-L1', 'NovaQuad Instruments (NL-100 / 7-satellite mission)', 'GSLV-F14 / INSAT-3DS'], correctIndex: 2, explanation: 'ISRO\'s 100th mission from Sriharikota (SDSC SHAR) was launched on 21 October 2024. It deployed a set of satellites including NovaQuad Instruments\' NL-100 and others, using PSLV-C60.', source: 'ISRO official website / PSLV-C60 mission report', difficulty: 'hard' },
  { slug: 'gk-nbcc-india-role', categoryId: 'cat-gk', text: 'The Central Vista Redevelopment Project in New Delhi is being executed by which government entity?', options: ['CPWD', 'NBCC (India) Limited', 'L&T Construction', 'Tata Projects'], correctIndex: 0, explanation: 'The Central Vista Redevelopment Project, including the new Parliament building, is being executed by CPWD (Central Public Works Department), with Tata Projects as the contractor for the Parliament building. The new Parliament was inaugurated on 28 May 2023.', source: 'Ministry of Housing and Urban Affairs / CPWD', difficulty: 'medium' },
  { slug: 'gk-indian-coast-guard-established', categoryId: 'cat-gk', text: 'The Indian Coast Guard was formally established in which year?', options: ['1965', '1971', '1978', '1982'], correctIndex: 2, explanation: 'The Indian Coast Guard was formally established on 1 February 1977 by the Coast Guard Act, 1978. It was formally constituted on 18 August 1978 as an armed force of the Union for maritime security and law enforcement.', source: 'Indian Coast Guard / Ministry of Defence', difficulty: 'medium' },
  { slug: 'gk-largest-mosque-india', categoryId: 'cat-gk', text: 'Which is the largest mosque in India by courtyard area?', options: ['Jama Masjid, Delhi', 'Taj-ul-Masajid, Bhopal', 'Mecca Masjid, Hyderabad', 'Bara Imambara, Lucknow'], correctIndex: 1, explanation: 'Taj-ul-Masajid ("Crown Among Mosques") in Bhopal is the largest mosque in India by courtyard area. It has a capacity of approximately 175,000 worshippers. Construction began in the 19th century during the reign of Nawab Shah Jahan Begum and was completed in 1985.', source: 'Madhya Pradesh Tourism / Archaeological Survey of India', difficulty: 'hard' },
  { slug: 'gk-right-to-recall-tribal', categoryId: 'cat-gk', text: 'In India, the system of "right to recall" elected representatives exists in which form of local governance?', options: ['Only in urban municipalities', 'In Gram Panchayats (village councils) in some states', 'At the national level for MPs', 'It does not exist in any form'], correctIndex: 1, explanation: 'The "right to recall" elected representatives exists in some Panchayati Raj institutions. States like Madhya Pradesh, Chhattisgarh, and Bihar have introduced recall provisions for Gram Panchayat members. There is no right to recall at the state or national level.', source: 'Ministry of Panchayati Raj / State Election Commissions', difficulty: 'hard' },
  { slug: 'gk-ood-regional-office-isro', categoryId: 'cat-gk', text: 'ISRO\'s Satish Dhawan Space Centre (SDSC SHAR), India\'s primary spaceport, is located on which island?', options: ['Sriharikota Island', 'Div Island', 'Willingdon Island', 'Pamban Island'], correctIndex: 0, explanation: 'SDSC SHAR is located on Sriharikota Island, a spindle-shaped barrier island off the coast of Andhra Pradesh, about 100 km north of Chennai. It was renamed in 2002 after Prof. Satish Dhawan, the third ISRO Chairman.', source: 'ISRO / Department of Space', difficulty: 'medium' },

  // ═══ cat-history: Indian History (10) ═══
  { slug: 'hist-dholavira-unesco-year', categoryId: 'cat-history', text: 'Dholavira, a Harappan city in Gujarat, was inscribed as a UNESCO World Heritage Site in which year?', options: ['2016', '2019', '2021', '2023'], correctIndex: 2, explanation: 'Dholavira was inscribed as a UNESCO World Heritage Site in July 2021. It is the first Indus Valley Civilisation site in India to receive this recognition. Located in the Rann of Kutch, it is notable for its sophisticated water conservation system.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'hist-ashoka-dhamma-pillars', categoryId: 'cat-history', text: 'The Ashoka Pillar at Sarnath, whose capital is India\'s national emblem, features how four lions facing which directions?', options: ['North, South, East, West', 'Only outward in all directions', 'North, South, East, and a Dharma Chakra (wheel) was originally on top', 'All four face east'], correctIndex: 2, explanation: 'The four lions on the Sarnath capital face the four cardinal directions: north, south, east, and west. Originally, a Dharma Chakra (Wheel of Law, with 24 spokes) was mounted on top. The chakra is now depicted separately as the Ashoka Chakra on the Indian flag.', source: 'Archaeological Survey of India / National Museum', difficulty: 'medium' },
  { slug: 'hist-1857-begum-awadh', categoryId: 'cat-history', text: 'Which queen led the 1857 revolt from Awadh (Lucknow)?', options: ['Rani Lakshmibai', 'Begum Hazrat Mahal', 'Rani Durgavati', 'Chennamma of Kittur'], correctIndex: 1, explanation: 'Begum Hazrat Mahal (also known as Begum of Awadh) led the revolt of 1857 from Lucknow after her husband Nawab Wajid Ali Shah was exiled. She seized control of Lucknow and declared her son Birjis Qadra as Nawab, before retreating to Nepal.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-buddhist-university-takshashila', categoryId: 'cat-history', text: 'The ancient university of Takshashila (Taxila) was located in which present-day region?', options: ['Modern-day Bihar, India', 'Modern-day Punjab, Pakistan', 'Modern-day Afghanistan', 'Modern-day Uzbekistan'], correctIndex: 1, explanation: 'Takshashila (Taxila) was located in present-day Punjab, Pakistan, near Islamabad. It was a renowned centre of learning from c. 600 BCE to 500 CE and is a UNESCO World Heritage Site. Chanakya, Panini, and Charaka are said to have studied and taught there.', source: 'UNESCO World Heritage List / Archaeological Survey of Pakistan', difficulty: 'medium' },
  { slug: 'hist-delhi-sultanate-khalji-allauddin', categoryId: 'cat-history', text: 'Alauddin Khalji is known for which significant administrative and military reform?', options: ['Abolishing the jizya tax', 'Fixing market prices for essential goods', 'Introducing the zamindari system', 'Establishing the Mansabdari system'], correctIndex: 1, explanation: 'Alauddin Khalji (r. 1296-1316) is known for his market reform policy — he fixed prices for essential goods, grains, and horses, enforced by strict punishment for violators. This was to maintain a large standing army at lower cost. He also repelled Mongol invasions.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-akbar-navaratna', categoryId: 'cat-history', text: 'Emperor Akbar had a council of nine extraordinary advisors known by what collective name?', options: ['Navaratnas (Nine Gems)', 'Ashtadiggajas', 'Mansabdars', 'Diwan-i-Arz'], correctIndex: 0, explanation: 'The "Navaratnas" (Nine Gems) were nine extraordinary advisors in Akbar\'s court. They included Birbal, Tansen, Todar Mal, Raja Man Singh, Abul Fazl, Faizi, Mulla Do-Piyaza, Tansen, and Abdul Rahim Khan-I-Khana. This concept existed earlier in Vikramaditya\'s court.', source: 'Indian Council of Historical Research / Abul Fazl\'s Akbarnama', difficulty: 'easy' },
  { slug: 'hist-mathura-art-school-buddha', categoryId: 'cat-history', text: 'The Mathura school of art is distinctive for producing which type of Buddha images?', options: ['Wearing monastic robes (samghati) with clear folds', 'Narrative scenes from Buddha\'s life only', 'Greek-inspired facial features', 'Sculptures made of metal only'], correctIndex: 0, explanation: 'The Mathura school of art (c. 1st century CE) is distinctive for producing Buddha images wearing monastic robes (samghati) with clear, parallel folds. This contrasts with the Gandhara school, which depicted Buddha in Greco-Roman drapery. Mathura used red sandstone.', source: 'Archaeological Survey of India / National Museum, New Delhi', difficulty: 'medium' },
  { slug: 'hist-cripps-mission-rejected', categoryId: 'cat-history', text: 'Why did the Indian National Congress reject the Cripps Mission proposal of 1942?', options: ['It offered independence immediately', 'It proposed dominion status after the war but no immediate self-government', 'It was too favourable to Muslims', 'It demanded India join World War II on the Axis side'], correctIndex: 1, explanation: 'The Congress rejected the Cripps Mission because it offered dominion status only after World War II, with no immediate transfer of power. Gandhi called it "a post-dated cheque on a crashing bank." The Muslim League rejected it because it didn\'t fully guarantee Pakistan.', source: 'National Archives of India / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-mountbatten-last-viceroy', categoryId: 'cat-history', text: 'Lord Mountbatten served as the last Viceroy of India and the first Governor-General of which country?', options: ['Independent India only', 'Both India and Pakistan', 'Pakistan only', 'Neither India nor Pakistan'], correctIndex: 0, explanation: 'Lord Mountbatten was the last Viceroy of British India (March-August 1947) and then served as the first Governor-General of independent India (1947-1948). Muhammad Ali Jinnah became the first Governor-General of Pakistan.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-gandhi-assassination-date', categoryId: 'cat-history', text: 'Mahatma Gandhi was assassinated on which date?', options: ['15 August 1947', '30 January 1948', '2 October 1948', '26 January 1950'], correctIndex: 1, explanation: 'Mahatma Gandhi was assassinated on 30 January 1948 by Nathuram Godse at Birla House (now Gandhi Smriti) in New Delhi. This day is observed as Martyrs\' Day (Shaheed Diwas) in India.', source: 'National Archives of India / Gandhi Memorial Museum', difficulty: 'easy' },

  // ═══ cat-geography: Geography (10) ═══
  { slug: 'geo-narmada-flow-direction', categoryId: 'cat-geography', text: 'The Narmada river flows in which direction?', options: ['Eastward into the Bay of Bengal', 'Westward into the Arabian Sea', 'Northward into the Ganga', 'Southward into the Indian Ocean'], correctIndex: 1, explanation: 'The Narmada flows westward into the Arabian Sea. It is one of the few major Indian rivers that flows westward, through a rift valley between the Vindhya and Satpura ranges. The Narmada is about 1,312 km long.', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'medium' },
  { slug: 'geo-highest-peak-western-ghats', categoryId: 'cat-geography', text: 'What is the highest peak in the Western Ghats?', options: ['Doddabetta', 'Anamudi', 'Mahabaleshwar', 'Nilgiri Peak'], correctIndex: 1, explanation: 'Anamudi (2,695 m / 8,842 ft) in Kerala\'s Eravikulam National Park is the highest peak in the Western Ghats and in South India. It is also the highest peak in India outside the Himalayan range.', source: 'Geological Survey of India / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-time-zone-single', categoryId: 'cat-geography', text: 'Despite spanning about 30° of longitude, India uses a single time zone. What is the time difference between the easternmost and westernmost parts of India (approximately)?', options: ['About 30 minutes', 'About 1 hour', 'About 2 hours', 'About 4 hours'], correctIndex: 2, explanation: 'India spans approximately 30° of longitude (from 68°7\'E to 97°25\'E), which corresponds to about 2 hours of solar time difference. Despite this, India uses a single time zone (IST = UTC+5:30), based on the 82.5°E meridian passing through Allahabad.', source: 'India Meteorological Department / Survey of India', difficulty: 'hard' },
  { slug: 'geo-largest-glacier-siachen', categoryId: 'cat-geography', text: 'The Siachen Glacier, one of the world\'s longest non-polar glaciers, is located in which mountain range?', options: ['Greater Himalayas', 'Karakoram Range', 'Pir Panjal Range', 'Zanskar Range'], correctIndex: 1, explanation: 'The Siachen Glacier (approximately 76 km long) is in the Karakoram Range in the eastern part of the range. It is the longest glacier in the Karakoram and one of the longest non-polar glaciers in the world. It is also the highest battlefield in the world.', source: 'Geological Survey of India / Ministry of Defence', difficulty: 'medium' },
  { slug: 'geo-andaman-nicobar-volcano-active', categoryId: 'cat-geography', text: 'India\'s only active volcano is located on which island in the Andaman & Nicobar archipelago?', options: ['Barren Island', 'Havelock Island', 'Ross Island', 'Neil Island'], correctIndex: 0, explanation: 'Barren Island hosts India\'s only active volcano. It is located about 135 km northeast of Port Blair. The volcano has erupted multiple times, most recently in 2018-2019. It is a stratovolcano rising from the Andaman Sea floor.', source: 'Geological Survey of India / Andaman & Nicobar Administration', difficulty: 'medium' },
  { slug: 'geo-pakistan-border-length', categoryId: 'cat-geography', text: 'India shares its longest international land border with which country?', options: ['China', 'Bangladesh', 'Pakistan', 'Nepal'], correctIndex: 1, explanation: 'India shares its longest international land border with Bangladesh — approximately 4,096 km (including West Bengal, Assam, Meghalaya, Tripura, and Mizoram). The India-Pakistan border is about 3,323 km and the India-China border is about 3,488 km.', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'geo-deccan-trap-formation', categoryId: 'cat-geography', text: 'The Deccan Traps, one of the world\'s largest volcanic provinces, were formed approximately how many million years ago?', options: ['About 5 million years ago', 'About 35 million years ago', 'About 66 million years ago', 'About 100 million years ago'], correctIndex: 2, explanation: 'The Deccan Traps were formed approximately 66 million years ago (near the Cretaceous-Paleogene boundary). This massive volcanic eruption covered much of west-central India with basalt lava. It is hypothesised to have contributed to the mass extinction that killed the dinosaurs.', source: 'Geological Survey of India', difficulty: 'hard' },
  { slug: 'geo-lakshadweep-capital', categoryId: 'cat-geography', text: 'What is the capital of the Union Territory of Lakshadweep?', options: ['Agatti', 'Kavaratti', 'Minicoy', 'Andrott'], correctIndex: 1, explanation: 'Kavaratti is the capital of Lakshadweep. It is the most developed island in the archipelago, located in the Arabian Sea off the southwestern coast of India. Lakshadweep consists of 36 islands, of which only 10 are inhabited.', source: 'Lakshadweep Administration / Ministry of Home Affairs', difficulty: 'easy' },
  { slug: 'geo-kolkata-port-river', categoryId: 'cat-geography', text: 'The city of Kolkata (Calcutta) is located on which river?', options: ['Hooghly (a distributary of the Ganga)', 'Damodar', 'Brahmaputra', 'Subarnarekha'], correctIndex: 0, explanation: 'Kolkata is located on the east bank of the Hooghly River, a distributary of the Ganga. The Hooghly flows about 260 km south to the Bay of Bengal. The Howrah Bridge (Rabindra Setu) spans the Hooghly, connecting Kolkata with Howrah.', source: 'Kolkata Metropolitan Development Authority / Survey of India', difficulty: 'easy' },
  { slug: 'geo-highest-waterfall-tiered', categoryId: 'cat-geography', text: 'Which waterfall in India is known for its three-tiered descent and is located in the Mhadei Wildlife Sanctuary, Goa?', options: ['Dudhsagar Falls', 'Jog Falls', 'Kunchikal Falls', 'Athirappilly Falls'], correctIndex: 0, explanation: 'Dudhsagar Falls (Sea of Milk) is a four-tiered waterfall on the Mandovi River on the Goa-Karnataka border. It is one of India\'s tallest waterfalls at about 310 m. It is located in the Bhagwan Mahaveer Sanctuary and Mollem National Park.', source: 'Geological Survey of India / Goa Tourism Department', difficulty: 'medium' },

  // ═══ cat-civics: Constitution & Civics (10) ═══
  { slug: 'civ-const-minorities-definition', categoryId: 'cat-civics', text: 'Under which Article of the Indian Constitution can the government establish and administer educational institutions for minorities?', options: ['Article 29', 'Article 30', 'Article 25', 'Article 32'], correctIndex: 1, explanation: 'Article 30 grants all minorities (religious or linguistic) the right to establish and administer educational institutions of their choice. Article 29 protects the cultural and educational rights of citizens with distinct language, script, or culture.', source: 'Constitution of India, Part III, Articles 29-30', difficulty: 'medium' },
  { slug: 'civ-money-bill-definition', categoryId: 'cat-civics', text: 'Under Article 110, a "Money Bill" can be introduced only in which house, and the other house can delay it for how long?', options: ['Rajya Sabha only; 14 days', 'Lok Sabha only; 14 days', 'Lok Sabha only; 6 months', 'Either house; 14 days'], correctIndex: 1, explanation: 'A Money Bill (Article 110) can be introduced only in the Lok Sabha. The Rajya Sabha can only make recommendations and must return it within 14 days. The Lok Sabha may accept or reject any recommendation. The Speaker certifies whether a bill is a Money Bill.', source: 'Constitution of India, Article 110', difficulty: 'medium' },
  { slug: 'civ-president-ordinance-power', categoryId: 'cat-civics', text: 'The President can promulgate an ordinance under which Article of the Constitution?', options: ['Article 123', 'Article 213', 'Article 248', 'Article 356'], correctIndex: 0, explanation: 'Article 123 empowers the President to promulgate ordinances when Parliament is not in session. An ordinance has the same force as a law but must be approved by Parliament within 6 weeks of reassembly, or it lapses. Article 213 gives similar power to Governors for states.', source: 'Constitution of India, Article 123', difficulty: 'medium' },
  { slug: 'civ-judicial-review-source', categoryId: 'cat-civics', text: 'The power of judicial review in India is derived from which Article of the Constitution?', options: ['Article 13', 'Article 14', 'Article 32', 'Article 226'], correctIndex: 0, explanation: 'Article 13 declares that any law inconsistent with or in derogation of the Fundamental Rights shall be void. This is the constitutional basis for judicial review in India. Articles 32 (Supreme Court) and 226 (High Courts) provide the mechanism to enforce this through writs.', source: 'Constitution of India, Article 13', difficulty: 'hard' },
  { slug: 'civ-vp-as-chairman-rs', categoryId: 'cat-civics', text: 'The Vice President of India serves as the ex-officio Chairman of which body?', options: ['Lok Sabha', 'Rajya Sabha (Council of States)', 'NITI Aayog', 'Inter-State Council'], correctIndex: 1, explanation: 'The Vice President of India is the ex-officio Chairman of the Rajya Sabha (Article 64). Unlike the Speaker of the Lok Sabha, the VP does not have a casting vote in the Rajya Sabha — they only vote in case of a tie, and only in the capacity of a regular member.', source: 'Constitution of India, Article 64', difficulty: 'easy' },
  { slug: 'civ-presidential-qualifications', categoryId: 'cat-civics', text: 'Which of the following is a qualification for the office of President of India?', options: ['Must be at least 25 years old', 'Must be at least 35 years old', 'Must have served as a Governor', 'Must be born in New Delhi'], correctIndex: 1, explanation: 'Article 58 requires the President to be at least 35 years old, a citizen of India, qualified to become a member of the Lok Sabha, and not hold any office of profit. The President serves a 5-year term.', source: 'Constitution of India, Article 58', difficulty: 'easy' },
  { slug: 'civ-special-status-jk-370', categoryId: 'cat-civics', text: 'Article 370, which granted special status to Jammu & Kashmir, was effectively abrogated in which year?', options: ['2014', '2017', '2019', '2022'], correctIndex: 2, explanation: 'Article 370 was effectively abrogated on 5 August 2019, when the President issued a constitutional order (C.O. 272) applying all provisions of the Indian Constitution to J&K. The state was reorganised into two Union Territories: J&K and Ladakh, effective 31 October 2019.', source: 'Constitution of India (Application to Jammu & Kashmir) Order, 2019', difficulty: 'medium' },
  { slug: 'civ-const-emergency-declared-1975', categoryId: 'cat-civics', text: 'The National Emergency declared on 25 June 1975 was under which Article and for what stated reason?', options: ['Article 352, due to "internal disturbance"', 'Article 356, due to failure of constitutional machinery', 'Article 360, due to financial crisis', 'Article 352, due to war'], correctIndex: 0, explanation: 'The National Emergency of 1975 was declared under Article 352 on the grounds of "internal disturbance" — the stated reason was threat from internal subversion. It lasted from 25 June 1975 to 21 March 1977 (21 months), and was the third and most controversial National Emergency in India\'s history.', source: 'Constitution of India, Article 352 / National Archives', difficulty: 'medium' },
  { slug: 'civ-first-amendment-1951', categoryId: 'cat-civics', text: 'The First Amendment to the Indian Constitution (1951) added which new provision?', options: ['The Ninth Schedule (to protect land reform laws from judicial review)', 'The Tenth Schedule (anti-defection law)', 'The Right to Education as a fundamental right', 'GST Council'], correctIndex: 0, explanation: 'The First Amendment Act of 1951 added the Ninth Schedule to the Constitution, intended to protect certain laws (particularly land reform laws) from judicial review on grounds of violating fundamental rights. It also added reasonable restrictions on freedom of speech.', source: 'Constitution of India, First Amendment Act, 1951', difficulty: 'hard' },
  { slug: 'civ-reservation-economically', categoryId: 'cat-civics', text: 'The 103rd Constitutional Amendment (2019) provided 10% reservation for which group?', options: ['Scheduled Castes in promotions', 'Economically Weaker Sections (EWS) in the general category', 'Additional reservation for OBCs', 'Women in Parliament'], correctIndex: 1, explanation: 'The 103rd Constitutional Amendment Act, 2019 introduced 10% reservation for the Economically Weaker Sections (EWS) among the general category in government jobs and educational institutions. This was upheld by the Supreme Court in 2022.', source: 'Constitution of India, 103rd Amendment Act, 2019', difficulty: 'medium' },

  // ═══ cat-science: Science & Technology (10) ═══
  { slug: 'sci-iron-pillar-delhi-rustless', categoryId: 'cat-science', text: 'The Iron Pillar of Delhi, known for its rust resistance, dates back to approximately which period?', options: ['500 BCE', '200 BCE - 400 CE (Mauryan/Gupta era)', '1000 CE', '1500 CE'], correctIndex: 1, explanation: 'The Iron Pillar of Delhi (Qutub Complex) dates to approximately 200 BCE - 400 CE (Mauryan or Gupta era). Standing 7.2 m tall, it is famous for its resistance to rust despite being exposed to the elements for over 1,600 years. This is due to its phosphorus-rich composition forming a protective layer.', source: 'Archaeological Survey of India / Indian Institute of Technology, Kanpur', difficulty: 'medium' },
  { slug: 'sci-aryabhata-zero-pi', categoryId: 'cat-science', text: 'Aryabhata, the 5th-century Indian mathematician, is credited with which mathematical contribution?', options: ['Invention of logarithms', 'Approximating π (pi) to 4 decimal places and discussing zero', 'Inventing the Pythagorean theorem', 'Developing calculus'], correctIndex: 1, explanation: 'Aryabhata (476-550 CE) approximated π to 3.1416 (4 decimal places) and discussed the concept of zero and place-value system in his "Aryabhatiya" (499 CE). He also calculated the Earth\'s circumference with remarkable accuracy and proposed that the Earth rotates on its axis.', source: 'Indian National Science Academy (INSA)', difficulty: 'medium' },
  { slug: 'sci-indian-vaccine-covishield-maker', categoryId: 'cat-science', text: 'Covishield, the COVID-19 vaccine manufactured in India, was produced by which company under license from AstraZeneca?', options: ['Bharat Biotech', 'Serum Institute of India (SII)', 'Biological E', 'Zydus Cadila'], correctIndex: 1, explanation: 'Covishield was manufactured by the Serum Institute of India (SII) in Pune under license from AstraZeneca and the University of Oxford. SII is the world\'s largest vaccine manufacturer by number of doses produced and exported.', source: 'Serum Institute of India / Ministry of Health and Family Welfare', difficulty: 'easy' },
  { slug: 'sci-brahmos-missile-origin', categoryId: 'cat-science', text: 'The BrahMos supersonic cruise missile is a joint venture between India and which country?', options: ['United States', 'Russia', 'France', 'Israel'], correctIndex: 1, explanation: 'BrahMos is a joint venture between India\'s DRDO and Russia\'s NPO Mashinostroyenia. It is a supersonic cruise missile (speed ~Mach 2.8-3.0) that can be launched from land, sea, air, and submarine. The name "BrahMos" comes from the Brahmaputra and Moskva rivers.', source: 'DRDO / BrahMos Aerospace', difficulty: 'medium' },
  { slug: 'sci-chandrayaan-3-landing-date', categoryId: 'cat-science', text: 'Chandrayaan-3 successfully landed on the Moon\'s south polar region on which date?', options: ['14 July 2023', '23 August 2023', '2 September 2023', '16 October 2023'], correctIndex: 1, explanation: 'Chandrayaan-3\'s Vikram lander successfully soft-landed on the Moon on 23 August 2023, making India the first country to land near the lunar south pole. The Pragyan rover then deployed and conducted experiments. The landing site was named "Shiva Shakti Point".', source: 'ISRO official website', difficulty: 'medium' },
  { slug: 'sci-indian-supercomputer-param-siddhi', categoryId: 'cat-science', text: 'Param Siddhi, one of India\'s most powerful supercomputers, was ranked in the top 100 globally when it was commissioned in which year?', options: ['2016', '2018', '2020', '2023'], correctIndex: 2, explanation: 'Param Siddhi was commissioned in 2020 by C-DAC under the National Supercomputing Mission. It was ranked 63rd in the Top500 global supercomputing list (November 2020), with a peak performance of 5.267 petaflops. It is used for AI, healthcare, and space applications.', source: 'C-DAC / Ministry of Electronics and IT (MeitY)', difficulty: 'hard' },
  { slug: 'sci-national-space-day-india', categoryId: 'cat-science', text: 'India celebrated its first National Space Day on 23 August 2024 to commemorate which achievement?', options: ['ISRO\'s founding', 'Chandrayaan-3 Moon landing', 'Mangalyaan Mars orbit insertion', 'Aditya-L1 launch'], correctIndex: 1, explanation: 'India celebrated its first National Space Day on 23 August 2024, marking the first anniversary of Chandrayaan-3\'s successful Moon landing (23 August 2023). The government designated 23 August as National Space Day to celebrate the milestone.', source: 'ISRO / Department of Space, Government of India', difficulty: 'medium' },
  { slug: 'sci-gaganyaan-mission-goal', categoryId: 'cat-science', text: 'The Gaganyaan mission aims to achieve what specific milestone for India?', options: ['Land on the Moon', 'Send Indian astronauts to the International Space Station', 'Send Indian astronauts to low-Earth orbit', 'Launch a space station'], correctIndex: 2, explanation: 'Gaganyaan aims to send a crew of 3 Indian astronauts (vyomanauts) to low-Earth orbit (~400 km altitude) for up to 7 days. The target launch was initially 2022 but has been delayed. ISRO conducted unmanned test flights in 2023-2024. If successful, India will become the 4th country to independently send humans to space.', source: 'ISRO official website / Department of Space', difficulty: 'medium' },
  { slug: 'sci-electric-vehicle-fame2', categoryId: 'cat-science', text: 'The FAME India Scheme (Faster Adoption and Manufacturing of Electric Vehicles) is administered by which ministry?', options: ['Ministry of Power', 'Ministry of Heavy Industries', 'Ministry of Road Transport', 'Ministry of New and Renewable Energy'], correctIndex: 1, explanation: 'The FAME India Scheme is administered by the Ministry of Heavy Industries. FAME-II (launched 2019, Rs. 10,000 crore outlay) subsidised electric two-wheelers, three-wheelers, four-wheelers, and buses. It ended in March 2024 and was succeeded by the Electric Mobility Promotion Scheme (EMPS).', source: 'Ministry of Heavy Industries, Government of India', difficulty: 'medium' },
  { slug: 'sci-isro-lvm3-rocket-name', categoryId: 'cat-science', text: 'LVM3 (Launch Vehicle Mark 3), ISRO\'s heaviest rocket, was previously known by what name?', options: ['GSLV Mk I', 'GSLV Mk II', 'GSLV Mk III', 'PSLV-XL'], correctIndex: 2, explanation: 'LVM3 was previously called GSLV Mk III (Geosynchronous Satellite Launch Vehicle Mark III). ISRO renamed it to LVM3 because it can launch satellites to LEO (low-Earth orbit) as well, not just geosynchronous orbit. LVM3 launched Chandrayaan-2, Chandrayaan-3, and Aditya-L1.', source: 'ISRO official website', difficulty: 'medium' },

  // ═══ cat-sports: Sports (10) ═══
  { slug: 'spt-olympic-2024-medals-india', categoryId: 'cat-sports', text: 'How many medals did India win at the 2024 Paris Olympics?', options: ['3', '5', '6', '8'], correctIndex: 2, explanation: 'India won 6 medals at the Paris 2024 Olympics: 1 silver (Neeraj Chopra, javelin throw) and 5 bronze (Manu Bhaker, shooting; Sarabjot Singh, shooting; Swapnil Kusale, shooting; Indian men\'s hockey team; Aman Sehrawat, wrestling). India finished 71st in the medal tally.', source: 'International Olympic Committee (IOC) / Indian Olympic Association', difficulty: 'medium' },
  { slug: 'spt-world-cup-cricket-2011-final-mom', categoryId: 'cat-sports', text: 'Who was named Player of the Match in the 2011 Cricket World Cup final?', options: ['Sachin Tendulkar', 'MS Dhoni', 'Yuvraj Singh', 'Gautam Gambhir'], correctIndex: 1, explanation: 'MS Dhoni was named Player of the Match in the 2011 ICC Cricket World Cup final against Sri Lanka. He scored an unbeaten 91 off 79 balls and hit the winning six. Yuvraj Singh was named Player of the Tournament.', source: 'ICC Cricket World Cup records / ESPN Cricinfo', difficulty: 'medium' },
  { slug: 'spt-chess-praggnanandhaa-world-cup', categoryId: 'cat-sports', text: 'Rameshbabu Praggnanandhaa reached the final of the FIDE Chess World Cup in 2023, losing to whom?', options: ['Magnus Carlsen', 'Ding Liren', 'Fabiano Caruana', 'Hikaru Nakamura'], correctIndex: 0, explanation: 'Praggnanandhaa reached the final of the FIDE Chess World Cup 2023 in Baku, Azerbaijan, losing to Magnus Carlsen in the final. By reaching the final, Praggnanandhaa qualified for the Candidates Tournament — the first Indian since Viswanathan Anand to do so.', source: 'World Chess Federation (FIDE)', difficulty: 'medium' },
  { slug: 'spt-hockey-india-captain-tokyo', categoryId: 'cat-sports', text: 'Who captained the Indian men\'s hockey team to the bronze medal at the Tokyo 2020 Olympics (held in 2021)?', options: ['Manpreet Singh', 'PR Sreejesh', 'Harmanpreet Singh', 'Rupinder Pal Singh'], correctIndex: 0, explanation: 'Manpreet Singh captained the Indian men\'s hockey team that won bronze at Tokyo 2020 (2021), ending a 41-year Olympic hockey medal drought. India defeated Germany 5-4 in the bronze medal match. Goalkeeper PR Sreejesh made a crucial save in the final seconds.', source: 'International Hockey Federation (FIH) / Hockey India', difficulty: 'medium' },
  { slug: 'spt-badminton-world-championship-sindhu', categoryId: 'cat-sports', text: 'PV Sindhu became the first Indian woman to win a gold medal at the BWF World Championships in which year?', options: ['2017', '2019', '2021', '2023'], correctIndex: 1, explanation: 'PV Sindhu won gold at the 2019 BWF World Championships in Basel, Switzerland, defeating Nozomi Okuhara in the final. She became the first Indian woman to become a world champion in badminton. She has won 5 World Championship medals (1 gold, 2 silver, 2 bronze).', source: 'Badminton World Federation (BWF)', difficulty: 'medium' },
  { slug: 'spt-athletics-neeraj-throw-distance', categoryId: 'cat-sports', text: 'Neeraj Chopra won Olympic gold at Tokyo 2020 with a throw of how many metres?', options: ['85.58 m', '87.58 m', '88.07 m', '89.94 m'], correctIndex: 1, explanation: 'Neeraj Chopra won gold at Tokyo 2020 with a best throw of 87.58 m in the javelin throw final on 7 August 2021. He became the first Indian track-and-field athlete to win Olympic gold. His personal best is 89.94 m (Stockholm Diamond League, 2022).', source: 'World Athletics / Athletics Federation of India', difficulty: 'medium' },
  { slug: 'spt-cricket-bumrah-test-vice-captain', categoryId: 'cat-sports', text: 'Jasprit Bumrah became India\'s Test vice-captain in 2024 and captained India in which Test match?', options: ['1st Test vs England (Hyderabad, 2024)', '1st Test vs Australia (Perth, 2024)', '3rd Test vs England (Rajkot, 2024)', '2nd Test vs Bangladesh (Kanpur, 2024)'], correctIndex: 1, explanation: 'Jasprit Bumrah captained India in the 1st Test against Australia at Perth (November 2024) in the absence of regular captain Rohit Sharma. India won the match by 295 runs. Bumrah was later named vice-captain for the series.', source: 'BCCI / ESPN Cricinfo', difficulty: 'hard' },
  { slug: 'spt-kabaddi-origin-india', categoryId: 'cat-sports', text: 'Kabaddi, India\'s indigenous contact sport, is believed to have originated approximately how many years ago?', options: ['About 100 years ago', 'About 500 years ago', 'About 1,000-2,000 years ago', 'About 4,000+ years ago'], correctIndex: 3, explanation: 'Kabaddi is believed to have originated in ancient India over 4,000 years ago. It is mentioned in the Mahabharata (the story of Abhimanyu\'s chakravyuha). The modern standardized rules were formulated in the 20th century. India has won all editions of the Kabaddi World Cup (men\'s standard format).', source: 'Amateur Kabaddi Federation of India / International Kabaddi Federation', difficulty: 'medium' },
  { slug: 'spt-wrestling-aman-sehrawat-2024', categoryId: 'cat-sports', text: 'Aman Sehrawat won India\'s sixth medal at the Paris 2024 Olympics in which sport and weight category?', options: ['Boxing, 57 kg', 'Wrestling, 57 kg freestyle', 'Shooting, 10m air pistol', 'Badminton, men\'s singles'], correctIndex: 1, explanation: 'Aman Sehrawat won bronze in the 57 kg freestyle wrestling at the Paris 2024 Olympics. At 21 years old, he became the youngest Indian Olympic medalist. He defeated Darian Cruz of Puerto Rico 13-5 in the bronze medal match.', source: 'International Olympic Committee / Wrestling Federation of India', difficulty: 'hard' },
  { slug: 'spt-indian-football-captain-chhetri-retire', categoryId: 'cat-sports', text: 'Sunil Chhetri, India\'s most capped football player, announced his international retirement in which year?', options: ['2022', '2023', '2024', '2025'], correctIndex: 2, explanation: 'Sunil Chhetri announced his retirement from international football in June 2024. He played his final match (his 151st cap) on 6 June 2024 against Kuwait. With 94 international goals, he was the 4th highest goalscorer in international football (after Ronaldo, Messi, and Ali Daei) at the time of retirement.', source: 'All India Football Federation (AIFF) / FIFA', difficulty: 'medium' },

  // ═══ cat-culture: Culture & Heritage (10) ═══
  { slug: 'cul-holi-festival-significance', categoryId: 'cat-culture', text: 'The festival of Holi is celebrated on which Hindu calendar month?', options: ['Chaitra (March-April)', 'Phalguna (February-March)', 'Kartika (October-November)', 'Bhadrapada (August-September)'], correctIndex: 1, explanation: 'Holi is celebrated on the full moon day (Purnima) of the Phalguna month (February-March). It marks the arrival of spring and the triumph of good over evil (symbolised by the Holika bonfire). The festival of colors is celebrated on the following day (Dhulendi).', source: 'Ministry of Culture, Government of India', difficulty: 'easy' },
  { slug: 'cul-eid-festival-name-meaning', categoryId: 'cat-culture', text: 'What does the word "Eid-ul-Fitr" literally mean?', options: ['Festival of fasting', 'Festival of breaking the fast', 'Festival of sacrifice', 'Festival of prayer'], correctIndex: 1, explanation: '"Eid-ul-Fitr" literally means the "Festival of Breaking the Fast." It marks the end of the holy month of Ramadan, during which Muslims fast from dawn to dusk. It is celebrated on the first day of Shawwal (the 10th month of the Islamic calendar).', source: 'Ministry of Minority Affairs / Islamic Cultural Centre of India', difficulty: 'easy' },
  { slug: 'cul-qutub-minar-height', categoryId: 'cat-culture', text: 'The Qutub Minar in Delhi is approximately how tall?', options: ['53 m', '73 m', '83 m', '100 m'], correctIndex: 1, explanation: 'The Qutub Minar is approximately 73 m (239 ft) tall, making it the tallest brick minaret in the world. It was begun by Qutb-ud-din Aibak in 1199 and completed by Iltutmish in 1220. It is a UNESCO World Heritage Site, part of the Qutub Complex.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-amer-fort-jaipur', categoryId: 'cat-culture', text: 'The Amer Fort (Amber Fort) in Jaipur is an excellent example of which architectural style?', options: ['Dravidian architecture', 'Indo-Islamic (Rajput-Mughal) architecture', 'Gothic architecture', 'Tibetan architecture'], correctIndex: 1, explanation: 'Amer Fort is an excellent example of Indo-Islamic (Rajput-Mughal) architecture, combining Hindu Rajput elements (like ornate gates and temples) with Islamic features (like arches and domes). Built by Raja Man Singh I in 1592, it is part of the UNESCO-listed "Hill Forts of Rajasthan."', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-rashtrapati-bhavan-garden-name', categoryId: 'cat-culture', text: 'The famous Mughal Gardens within the Rashtrapati Bhavan complex were designed by whom?', options: ['Edwin Lutyens', 'Herbert Baker', 'Walter George', 'Robert Tor Russell'], correctIndex: 0, explanation: 'The Mughal Gardens were designed by Edwin Lutyens, the architect who also designed the Rashtrapati Bhavan (Viceroy\'s House). The gardens combine Mughal-style terracing with British formal garden design, featuring fountains, canals, and flower beds. They are open to the public annually (Udyanotsav).', source: 'Rashtrapati Bhavan / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-sun-temple-konark-wheel-use', categoryId: 'cat-culture', text: 'The 24 wheels carved on the Konark Sun Temple are believed to represent what?', options: ['The 24 avatars of Vishnu', 'The 24 hours of the day', 'The 24 spokes of the Dharma Chakra', 'The 24 solar terms'], correctIndex: 1, explanation: 'The 24 wheels of the Konark Sun Temple are believed to represent the 24 hours of the day. The temple itself is designed as a chariot of the Sun God Surya, with 12 pairs of wheels (one for each month) and 7 horses (representing the 7 days of the week or the 7 colors of light).', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-jantar-mantar-jaipur-purpose', categoryId: 'cat-culture', text: 'The Jantar Mantar observatory in Jaipur was built for what primary purpose?', options: ['Military observation', 'Astronomical observation and time-keeping', 'Royal entertainment', 'Weather forecasting'], correctIndex: 1, explanation: 'The Jantar Mantar in Jaipur (built 1728-1734 by Maharaja Sawai Jai Singh II) was built for astronomical observation and time-keeping. It contains 19 instruments for measuring time, predicting eclipses, tracking stars, and determining celestial declinations. It is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-classical-music-tansen-tomb', categoryId: 'cat-culture', text: 'The tomb of the legendary Mughal musician Tansen is located in which city?', options: ['Delhi', 'Agra', 'Gwalior', 'Lucknow'], correctIndex: 2, explanation: 'Tansen\'s tomb is in Gwalior, Madhya Pradesh. He was one of the "Navaratnas" (Nine Gems) in Akbar\'s court and is considered one of the greatest musicians in Indian history. An annual music festival (Tansen Sangeet Sammelan) is held near his tomb each December.', source: 'Ministry of Culture / Madhya Pradesh Tourism', difficulty: 'medium' },
  { slug: 'cul-thanjavur-brihadeshwara-builder', categoryId: 'cat-culture', text: 'The Brihadeshwara Temple (Big Temple) in Thanjavur was built by which Chola king?', options: ['Rajaraja Chola I', 'Rajendra Chola I', 'Kulottunga Chola I', 'Vijayalaya Chola'], correctIndex: 0, explanation: 'The Brihadeshwara Temple was built by Rajaraja Chola I (r. 985-1014 CE) and completed around 1010 CE. It is a UNESCO World Heritage Site and one of the largest temples in India. Its vimana (tower) is about 66 m tall, and the temple is made entirely of granite.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-elephanta-caves-island-name', categoryId: 'cat-culture', text: 'The Elephanta Caves are located on an island in which body of water, near Mumbai?', options: ['Arabian Sea', 'Bay of Bengal', 'Indian Ocean', 'Gulf of Kutch'], correctIndex: 0, explanation: 'The Elephanta Caves are on Elephanta Island (Gharapuri) in the Arabian Sea, about 10 km east of Mumbai. The island was named "Elephanta" by the Portuguese after a large stone elephant statue that once stood there (now in the Bhau Daji Lad Museum, Mumbai). It is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'easy' },

  // ═══ cat-economy: Economy (10) ═══
  { slug: 'eco-uPI-transactions-volume', categoryId: 'cat-economy', text: 'Unified Payments Interface (UPI), India\'s digital payment system, processes approximately how many transactions per month (as of 2024)?', options: ['About 1 billion', 'About 5 billion', 'About 10-14 billion', 'About 50 billion'], correctIndex: 2, explanation: 'As of 2024, UPI processes approximately 10-14 billion transactions per month. India accounts for about 46% of all real-time digital payment transactions worldwide. UPI was launched in 2016 by NPCI and has become the world\'s largest real-time payment system.', source: 'National Payments Corporation of India (NPCI) / Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-credit-card-sbi-card', categoryId: 'cat-economy', text: 'SBI Card, India\'s largest credit card issuer, is a joint venture between State Bank of India and which other entity?', options: ['HDFC Bank', 'Citibank', 'GE Capital', 'Visa International'], correctIndex: 2, explanation: 'SBI Card was originally a joint venture between SBI and GE Capital (established 1998). In 2017, SBI and GE Capital sold a stake to Carlyle Group. SBI Card was listed on the stock exchanges in March 2020 (SBI Cards and Payment Services Ltd).', source: 'SBI Card / Securities and Exchange Board of India (SEBI)', difficulty: 'hard' },
  { slug: 'eco-tax-revenue-direct-indirect', categoryId: 'cat-economy', text: 'India\'s tax structure is divided into direct taxes and indirect taxes. Which of the following is a direct tax?', options: ['Goods and Services Tax (GST)', 'Customs duty', 'Corporate income tax', 'Central excise duty'], correctIndex: 2, explanation: 'Corporate income tax is a direct tax (paid directly by the taxpayer to the government). GST, customs duty, and central excise duty are indirect taxes (collected by intermediaries like manufacturers/sellers from consumers). The CBDT (Central Board of Direct Taxes) administers direct taxes.', source: 'Ministry of Finance / CBDT / CBIC', difficulty: 'easy' },
  { slug: 'eco-inflation-targeting-framework', categoryId: 'cat-economy', text: 'India adopted a flexible inflation targeting framework in 2016. What is the RBI\'s target CPI inflation rate?', options: ['2% ± 1%', '4% ± 2%', '6% ± 2%', '8% ± 1%'], correctIndex: 1, explanation: 'India adopted flexible inflation targeting in 2016 (under the Monetary Policy Framework Agreement). The RBI\'s target is 4% CPI inflation with a tolerance band of ±2% (i.e., 2% to 6%). The Monetary Policy Committee (MPC), established in 2016, sets the policy rate to achieve this target.', source: 'Reserve Bank of India / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-disinvestment-target-2024', categoryId: 'cat-economy', text: 'The Government of India sets annual disinvestment targets. What was the disinvestment target for FY 2023-24 (approximately)?', options: ['Rs. 25,000 crore', 'Rs. 51,000 crore', 'Rs. 75,000 crore', 'Rs. 1,75,000 crore'], correctIndex: 1, explanation: 'The disinvestment target for FY 2023-24 was Rs. 51,000 crore. The government typically falls short of disinvestment targets. The DIPAM (Department of Investment and Public Asset Management) oversees the disinvestment process for central public sector enterprises (CPSEs).', source: 'Union Budget 2023-24 / Department of Investment and Public Asset Management (DIPAM)', difficulty: 'hard' },
  { slug: 'eco-lic-ipo-year', categoryId: 'cat-economy', text: 'Life Insurance Corporation of India (LIC), India\'s largest insurer, conducted its IPO in which year?', options: ['2020', '2021', '2022', '2023'], correctIndex: 2, explanation: 'LIC\'s IPO was conducted in May 2022. At approximately Rs. 21,000 crore, it was India\'s largest IPO to date. The Government of India sold a 3.5% stake in LIC. LIC was established in 1956 when 245 insurance companies were nationalised and merged.', source: 'Securities and Exchange Board of India (SEBI) / LIC', difficulty: 'medium' },
  { slug: 'eco-msme-sector-gdp-share', categoryId: 'cat-economy', text: 'The MSME (Micro, Small and Medium Enterprises) sector contributes approximately what percentage to India\'s GDP (as of 2023-24)?', options: ['About 10%', 'About 30%', 'About 45%', 'About 60%'], correctIndex: 1, explanation: 'The MSME sector contributes approximately 30% to India\'s GDP. It also accounts for about 48% of India\'s exports and employs over 110 million people. There are approximately 63 million MSMEs in India (as of the 2023 Udyam Registration Portal data).', source: 'Ministry of Micro, Small and Medium Enterprises / Udyam Registration Portal', difficulty: 'medium' },
  { slug: 'eco-rupee-de-dollarisation', categoryId: 'cat-economy', text: 'The RBI\'s "Special Rupee Vostro Account" (SRVA) mechanism, launched in 2022, aims to achieve what?', options: ['Replace the US dollar in all trade', 'Enable international trade settlements in Indian rupees', 'Devalue the rupee', 'Link the rupee to the euro'], correctIndex: 1, explanation: 'The Special Rupee Vostro Account (SRVA) mechanism, launched in 2022, enables international trade settlements in Indian rupees, reducing dependence on the US dollar. Banks from partner countries can open Vostro accounts with Indian banks to settle trade in rupees.', source: 'Reserve Bank of India / Ministry of Commerce', difficulty: 'hard' },
  { slug: 'eco-india-fintech-rank', categoryId: 'cat-economy', text: 'India is ranked what in the global fintech market (by adoption rate, as of 2023)?', options: ['1st', '3rd', '5th', '10th'], correctIndex: 0, explanation: 'India has the highest fintech adoption rate globally (approximately 87%, compared to the global average of 64%). India\'s fintech market is the 3rd largest by funded start-ups (after the US and UK). Key drivers include UPI, Aadhaar, Jan Dhan, and mobile penetration.', source: 'NASSCOM / EY Fintech Report / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-income-tax-slabs-new-regime', categoryId: 'cat-economy', text: 'Under the new tax regime (default from FY 2023-24), income up to what amount is exempt from income tax?', options: ['Rs. 2.5 lakh', 'Rs. 3 lakh', 'Rs. 5 lakh', 'Rs. 7 lakh'], correctIndex: 2, explanation: 'Under the new tax regime (default from FY 2023-24), income up to Rs. 3 lakh is exempt. With the rebate under Section 87A, individuals with taxable income up to Rs. 7 lakh effectively pay zero income tax. The new regime has lower rates but fewer deductions.', source: 'Income Tax Department / Ministry of Finance / Union Budget 2023-24', difficulty: 'medium' },

  // ═══ cat-environment: Environment & Wildlife (10) ═══
  { slug: 'env-elephant-population-india-2024', categoryId: 'cat-environment', text: 'According to the 2017 elephant census, India\'s wild elephant population is approximately how many?', options: ['About 10,000', 'About 17,000', 'About 27,000', 'About 40,000'], correctIndex: 2, explanation: 'The 2017 elephant census estimated approximately 27,312 wild elephants in India (down from 29,391-30,711 in 2012). India has the largest population of Asian elephants. Karnataka has the highest number, followed by Assam and Kerala.', source: 'Ministry of Environment, Forest and Climate Change / Project Elephant', difficulty: 'medium' },
  { slug: 'env-wild-assam-one-horned-rhino', categoryId: 'cat-environment', text: 'Kaziranga National Park hosts approximately what percentage of the world\'s one-horned rhino population?', options: ['About 30%', 'About 50%', 'About 70%', 'About 90%'], correctIndex: 2, explanation: 'Kaziranga National Park in Assam hosts approximately 70% of the world\'s one-horned rhinoceros (Indian rhino) population. The 2022 census counted 2,613 rhinos in Kaziranga. The total Indian rhino population is about 4,000, with smaller populations in Pobitora, Orang, and Dudhwa.', source: 'IUCN Red List / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-air-quality-index-aqi', categoryId: 'cat-environment', text: 'In India\'s National Air Quality Index (AQI), what does a reading of 401-500 indicate?', options: ['Good', 'Moderate', 'Poor', 'Severe+'], correctIndex: 3, explanation: 'India\'s National AQI (launched in 2014) has 6 categories: Good (0-50), Satisfactory (51-100), Moderate (101-200), Poor (201-300), Very Poor (301-400), and Severe+ (401-500). A reading of 401-500 indicates "Severe+" air quality, affecting healthy people and serious impact on those with existing illnesses.', source: 'Central Pollution Control Board (CPCB) / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-cop28-methane-pledge', categoryId: 'cat-environment', text: 'At COP28 in Dubai (2023), India declined to sign the Global Methane Pledge. Why?', options: ['India does not produce methane', 'The pledge targets agriculture and livestock, which are critical for India\'s rural economy and food security', 'India already has zero methane emissions', 'India considers methane not a greenhouse gas'], correctIndex: 1, explanation: 'India declined to sign the Global Methane Pledge (which aims to cut methane emissions by 30% by 2030) because the pledge targets agricultural and livestock emissions, which are critical for India\'s rural economy and food security. India\'s livestock population is the largest in the world.', source: 'UNFCCC COP28 / Ministry of Environment, Forest and Climate Change', difficulty: 'hard' },
  { slug: 'env-clean-ganga-impact-report', categoryId: 'cat-environment', text: 'The Namami Gange programme has led to the creation of approximately how many sewage treatment plants along the Ganga (as of 2023)?', options: ['About 10', 'About 50', 'About 100-150', 'About 300'], correctIndex: 2, explanation: 'As of 2023, the Namami Gange programme has created/sanctioned approximately 100-150 sewage treatment plants (STPs) along the Ganga, creating over 3,000 MLD (million litres per day) treatment capacity. The programme also includes riverfront development and biodiversity conservation.', source: 'National Mission for Clean Ganga (NMCG) / Ministry of Jal Shakti', difficulty: 'hard' },
  { slug: 'env-ramsar-india-latest-count', categoryId: 'cat-environment', text: 'How many Ramsar Sites (wetlands of international importance) did India have as of early 2024?', options: ['About 40', 'About 60', 'About 75-80', 'About 100'], correctIndex: 2, explanation: 'As of early 2024, India has approximately 75-80 Ramsar Sites (covering about 1.33 million hectares). India added the most sites in 2022 (10 new sites) and 2023. The largest Ramsar Site in India is Sunderbans Wetland (West Bengal).', source: 'Ministry of Environment, Forest and Climate Change / Ramsar Convention Secretariat', difficulty: 'medium' },
  { slug: 'env-solar-park-bhadla', categoryId: 'cat-environment', text: 'The Bhadla Solar Park, one of the world\'s largest solar parks, is located in which Indian state?', options: ['Gujarat', 'Rajasthan', 'Maharashtra', 'Madhya Pradesh'], correctIndex: 1, explanation: 'The Bhadla Solar Park is located in Rajasthan\'s Jodhpur district, in the Thar Desert. With a total capacity of 2,245 MW, it is one of the world\'s largest solar parks. It covers approximately 14,000 acres and was developed by RRECL (Rajasthan Renewable Energy Corporation Ltd).', source: 'Ministry of New and Renewable Energy (MNRE) / RRECL', difficulty: 'medium' },
  { slug: 'env-wildlife-bannerghatta', categoryId: 'cat-environment', text: 'Bannerghatta Biological Park, known for its butterfly park and lion/tiger safari, is located near which Indian city?', options: ['Chennai', 'Bengaluru', 'Hyderabad', 'Mysuru'], correctIndex: 1, explanation: 'Bannerghatta Biological Park is located near Bengaluru, Karnataka. It includes a zoo, a butterfly park (India\'s first), a safari park (with lions, tigers, and herbivores), and a rescue centre for wild animals. It covers about 260 sq km.', source: 'Karnataka Forest Department / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-cleantech-green-hydrogen', categoryId: 'cat-environment', text: 'India\'s National Green Hydrogen Mission was launched in which year with what target production capacity (by 2030)?', options: ['2020, 1 MMT', '2022, 5 MMT', '2023, 5 MMT', '2024, 10 MMT'], correctIndex: 1, explanation: 'The National Green Hydrogen Mission was launched on 4 January 2023 with an initial outlay of Rs. 19,744 crore. It aims to make India a global hub for green hydrogen production, targeting 5 MMT (million metric tonnes) annual production by 2030.', source: 'Ministry of New and Renewable Energy (MNRE)', difficulty: 'hard' },
  { slug: 'env-dolphins-ganga-flagship', categoryId: 'cat-environment', text: 'The Ganges River Dolphin is the national aquatic animal of India. It is also the state aquatic animal of which state/UT?', options: ['Uttar Pradesh', 'Bihar', 'Assam', 'All of the above and more'], correctIndex: 3, explanation: 'The Ganges River Dolphin (Platanista gangetica) is the national aquatic animal of India (declared in 2009). It is also the state aquatic animal of Uttar Pradesh, Bihar, Assam, and the state animal of Madhya Pradesh. It is blind (lacks a crystalline lens) and navigates using echolocation.', source: 'Ministry of Environment, Forest and Climate Change / IUCN Red List', difficulty: 'medium' },

  // ═══ cat-art: Art, Literature & Languages (10) ═══
  { slug: 'art-indian-epics-ramayana-versions', categoryId: 'cat-art', text: 'How many Sanskrit "Ramayana" versions (Kandas) are there in the standard Valmiki Ramayana?', options: ['Five', 'Six', 'Seven', 'Ten'], correctIndex: 2, explanation: 'The Valmiki Ramayana has seven Kandas (books): Bala Kanda, Ayodhya Kanda, Aranya Kanda, Kishkindha Kanda, Sundara Kanda, Yuddha Kanda, and Uttara Kanda. The Uttara Kanda is sometimes considered a later addition. The epic contains about 24,000 verses (shlokas) across 500 chapters (sargas).', source: 'Sahitya Akademi / Encyclopaedia Britannica', difficulty: 'medium' },
  { slug: 'art-kamayani-jaishankar-prasad', categoryId: 'cat-art', text: '"Kamayani", one of the greatest epic poems in modern Hindi literature, was written by whom?', options: ['Sumitranandan Pant', 'Jaishankar Prasad', 'Suryakant Tripathi Nirala', 'Mahadevi Verma'], correctIndex: 1, explanation: '"Kamayani" (1935) was written by Jaishankar Prasad (1889-1937). It is considered one of the greatest literary works in modern Hindi literature. The epic poem deals with human emotions (bhavas) and the interplay between man, nature, and the mind. Prasad was one of the four pillars (Char Ayam) of Chhayavad, the Hindi Romantic movement.', source: 'Sahitya Akademi / Hindi Sahitya Akademi', difficulty: 'hard' },
  { slug: 'art-pattachitra-painting-state', categoryId: 'cat-art', text: 'Pattachitra, a traditional cloth-based scroll painting, originates from which Indian state?', options: ['West Bengal', 'Odisha', 'Bihar', 'Jharkhand'], correctIndex: 1, explanation: 'Pattachitra originates from Odisha, particularly the Puri and Raghurajpur village areas. The paintings depict mythological narratives from the Ramayana, Mahabharata, and Lord Jagannath\'s life. They are painted on cloth (patta) using natural colours. The tradition dates back to at least the 5th century BCE.', source: 'Ministry of Culture / Odisha Tourism / Sangeet Natak Akademi', difficulty: 'medium' },
  { slug: 'art-gitanjali-poems-count', categoryId: 'cat-art', text: 'Rabindranath Tagore\'s "Gitanjali" (Song Offerings) contains how many poems in the English translation?', options: ['50', '103', '157', '200'], correctIndex: 2, explanation: 'The English version of "Gitanjali" (published 1912) contains 157 poems — 53 from the original Bengali "Gitanjhi" (1910) and 104 from other Bengali collections. The English translation was done by Tagore himself. He received the Nobel Prize for this work in 1913.', source: 'Nobel Prize Foundation / Visva-Bharati University', difficulty: 'medium' },
  { slug: 'art-sanskrit-grammar-panini-sutras', categoryId: 'cat-art', text: 'Panini\'s "Ashtadhyayi", the foundational Sanskrit grammar treatise, consists of how many sutras (rules)?', options: ['About 1,000', 'About 2,000', 'About 4,000', 'About 8,000'], correctIndex: 2, explanation: 'The "Ashtadhyayi" (Eight Chapters) by Panini (c. 4th century BCE) contains approximately 3,959 sutras (rules) across 8 chapters, with each chapter having 4 sections. It is one of the most sophisticated grammatical treatises ever produced and is considered a precursor to modern formal language theory.', source: 'Indian National Science Academy / Encyclopaedia Britannica', difficulty: 'hard' },
  { slug: 'art-tamil-sangam-literature-silappadikaram', categoryId: 'cat-art', text: 'The Tamil epic "Silappadikaram" (The Tale of an Anklet) was written by whom?', options: ['Ilango Adigal', 'Thiruvalluvar', 'Kambar', 'Avvaiyar'], correctIndex: 0, explanation: 'The "Silappadikaram" was written by Ilango Adigal, a Jain prince-turned-ascetic, approximately in the 2nd century CE. It is one of the five great epics of Tamil literature. It tells the story of Kannagi, her husband Kovalan, and the destruction of Madurai by her curse.', source: 'Sahitya Akademi / UNESCO Memory of the World', difficulty: 'medium' },
  { slug: 'art-raga-classification-hindustani', categoryId: 'cat-art', text: 'In Hindustani classical music, ragas are classified into how many thaats (parent scales)?', options: ['7', '10', '12', '16'], correctIndex: 1, explanation: 'The Hindustani classical music system classifies ragas into 10 thaats (parent scales), as codified by Pandit Vishnu Narayan Bhatkhande in the early 20th century. The 10 thaats are: Bilawal, Kalyan, Khamaj, Bhairav, Poorvi, Marwa, Kafi, Asavari, Bhairavi, and Todi.', source: 'Sangeet Natak Akademi', difficulty: 'hard' },
  { slug: 'art-fatehpur-sikri-architect', categoryId: 'cat-art', text: 'Fatehpur Sikri, the abandoned Mughal capital, was built by which emperor?', options: ['Humayun', 'Akbar', 'Shah Jahan', 'Babur'], correctIndex: 1, explanation: 'Fatehpur Sikri was built by Emperor Akbar (r. 1556-1605) as his capital from 1571 to 1585, when it was abandoned due to water shortage. It is a UNESCO World Heritage Site, featuring the Buland Darwaza, Jama Masjid, Panch Mahal, and Diwan-i-Khas. It exemplifies Indo-Islamic architecture.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'art-subramania-bharati', categoryId: 'cat-art', text: 'Subramania Bharati (1882-1921), one of the greatest Tamil poets, was also known by what title?', options: ['Mahakavi (Great Poet)', 'Kaviraj (King of Poets)', 'Shilpacharya (Great Teacher)', 'Kaviratna (Gem of Poets)'], correctIndex: 0, explanation: 'Subramania Bharati was known as "Mahakavi" (Great Poet). He was a pioneer of modern Tamil poetry and a key figure in the Indian independence movement. He wrote on themes of freedom, feminism, caste reform, and nationalism. His works include "Kuyil Pattu" (Song of the Cuckoo) and "Panchali Sapatham" (Vow of Panchali).', source: 'Sahitya Akademi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'art-hindustani-music-dhrupad-vs-khayal', categoryId: 'cat-art', text: 'What is the primary structural difference between Dhrupad and Khayal, two major styles of Hindustani vocal music?', options: ['Dhrupad uses only Sanskrit lyrics; Khayal uses Hindi/Urdu', 'Dhrupad has no rhythmic accompaniment; Khayal does', 'Dhrupad is more structured and grave; Khayal allows more improvisation and ornamentation', 'There is no difference'], correctIndex: 2, explanation: 'Dhrupad is the older, more structured, and grave style, emphasising pure melody (alap) and strict adherence to tala. Khayal (meaning "imagination") is a later style that allows more improvisation, ornamentation (alapi, taan), and emotional expression. Khayal is the most popular Hindustani vocal style today.', source: 'Sangeet Natak Akademi / ITC Sangeet Research Academy', difficulty: 'hard' },

  // ═══ cat-edu: Education (10) ═══
  { slug: 'edu-central-university-count-2024', categoryId: 'cat-edu', text: 'As of 2024, how many Central Universities are there in India?', options: ['About 25', 'About 40', 'About 55-56', 'About 75'], correctIndex: 2, explanation: 'As of 2024, there are approximately 55-56 Central Universities in India. The University Grants Commission (UGC) administers these. The first central university was Aligarh Muslim University (AMU, 1920), followed by Banaras Hindu University (BHU, 1916). The University of Delhi was established in 1922.', source: 'University Grants Commission (UGC) / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-navodaya-vidyalaya-count-2024', categoryId: 'cat-edu', text: 'As of 2024, approximately how many Jawahar Navodaya Vidyalayas (JNVs) are operational in India?', options: ['About 300', 'About 500', 'About 650-660', 'About 800'], correctIndex: 2, explanation: 'As of 2024, approximately 650-660 JNVs are operational across India (nearly one per district). JNVs are fully residential, co-educational schools for talented rural children, established under the National Education Policy 1986. They are administered by the Navodaya Vidyalaya Samiti (NVS) under the Ministry of Education.', source: 'Navodaya Vidyalaya Samiti / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-iits-newest-est-2015', categoryId: 'cat-edu', text: 'Which of the following IITs was established in 2015-2016?', options: ['IIT Bhubaneswar', 'IIT Gandhinagar', 'IIT Tirupati', 'IIT Indore'], correctIndex: 2, explanation: 'IIT Tirupati was established in 2015 (started in 2016). It was one of 6 new IITs announced in 2014-2015 under the 12th Five Year Plan. The others were IIT Bhilai, IIT Dharwad, IIT Jammu, IIT Palakkad, and IIT Goa. The total number of IITs is now 23.', source: 'Ministry of Education / IIT Council', difficulty: 'hard' },
  { slug: 'edu-ncert-full-form', categoryId: 'cat-edu', text: 'What does NCERT stand for?', options: ['National Council for Education and Research Training', 'National Council of Educational Research and Training', 'National Centre for Educational Research and Training', 'National Committee for Educational Research and Training'], correctIndex: 1, explanation: 'NCERT stands for "National Council of Educational Research and Training." It was established on 1 September 1961 as an autonomous organisation under the Ministry of Education. NCERT develops textbooks (NCERT books), conducts educational research, and trains teachers.', source: 'NCERT official website / Ministry of Education', difficulty: 'easy' },
  { slug: 'edu-swayam-prabha-channels', categoryId: 'cat-edu', text: 'SWAYAM Prabha is an initiative that provides educational content through which medium?', options: ['Internet only', '32 Direct-to-Home (DTH) TV channels via satellite', 'Radio only', 'Mobile app only'], correctIndex: 1, explanation: 'SWAYAM Prabha is a government initiative providing educational content through 32 Direct-to-Home (DTH) TV channels via GSAT-15 satellite. It was launched to deliver educational content to areas without internet access, complementing the SWAYAM online platform.', source: 'Ministry of Education / CEC / ISRO', difficulty: 'medium' },
  { slug: 'edu-icse-cisce', categoryId: 'cat-edu', text: 'ICSE (Indian Certificate of Secondary Education) examinations are conducted by which body?', options: ['CBSE', 'CISCE (Council for the Indian School Certificate Examinations)', 'NCERT', 'State Boards'], correctIndex: 1, explanation: 'ICSE examinations are conducted by the Council for the Indian School Certificate Examinations (CISCE), a private, non-governmental board of school education in India. CISCE also conducts the ISC (Indian School Certificate) for Class 12. The council was established in 1958.', source: 'CISCE official website / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-aiims-ug-medical-seats', categoryId: 'cat-edu', text: 'AIIMS New Delhi, the top-ranked medical institution in India, admits MBBS students through which entrance exam (since 2020)?', options: ['AIIMS entrance exam (separate)', 'NEET (National Eligibility cum Entrance Test)', 'JEE Main', 'CUET'], correctIndex: 1, explanation: 'Since 2020, AIIMS New Delhi admits MBBS students through NEET (National Eligibility cum Entrance Test), conducted by the National Testing Agency (NTA). Previously, AIIMS conducted its own entrance exam. NEET is now the sole entrance exam for MBBS/BDS admissions across all medical colleges in India.', source: 'National Testing Agency (NTA) / AIIMS / Ministry of Health', difficulty: 'medium' },
  { slug: 'edu-mooc-india-swayam-2016', categoryId: 'cat-edu', text: 'The SWAYAM MOOC platform was officially launched in which year?', options: ['2014', '2016', '2018', '2020'], correctIndex: 1, explanation: 'SWAYAM (Study Webs of Active-Learning for Young Aspiring Minds) was officially launched on 9 July 2016 by the Ministry of Education. It offers free online courses from Class 9 to postgraduate level, aligned to the UGC curriculum. Certification is available for a nominal fee.', source: 'Ministry of Education / SWAYAM portal', difficulty: 'medium' },
  { slug: 'edu-rte-25-percent-private', categoryId: 'cat-edu', text: 'Under the Right to Education (RTE) Act, 2009, private schools must reserve 25% of entry-level seats for children from which groups?', options: ['Only SC/ST children', 'Only EWS (Economically Weaker Sections)', 'Disadvantaged and EWS groups', 'Children of armed forces personnel'], correctIndex: 2, explanation: 'Section 12(1)(c) of the RTE Act requires all private (unaided) schools to reserve 25% of entry-level seats for children from "disadvantaged" and "Economically Weaker Sections (EWS)". The government reimburses their fees. This aims to promote social inclusion in education.', source: 'Ministry of Education / RTE Act, 2009, Section 12(1)(c)', difficulty: 'medium' },
  { slug: 'edu-skilling-pmkvy', categoryId: 'cat-edu', text: 'Pradhan Mantri Kaushal Vikas Yojana (PMKVY), India\'s flagship skill development scheme, is implemented by which body?', options: ['Ministry of Education', 'National Skill Development Corporation (NSDC)', 'AICTE', 'UGC'], correctIndex: 1, explanation: 'PMKVY is implemented by the National Skill Development Corporation (NSDC) under the Ministry of Skill Development and Entrepreneurship. Launched in 2015, it aims to train youth in industry-relevant skills and provide certification. PMKVY 4.0 was announced in Budget 2023-24.', source: 'Ministry of Skill Development and Entrepreneurship / NSDC', difficulty: 'medium' },
];

async function main() {
  console.log('=== Batch 4 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
